<section class="page-header"><div><span class="eyebrow">Billing & collections</span><h1>Invoices</h1><p>Tax-ready billing, partial payments and client outstanding balances.</p></div><div class="page-actions"><a class="button button-secondary" href="<?= url('reports?from='.date('Y-m-01').'&to='.date('Y-m-d')) ?>"><i class="fa-solid fa-chart-line"></i> Revenue report</a><?php if(can('invoices.create')):?><a class="button button-primary" href="<?= url('invoices/create') ?>"><i class="fa-solid fa-plus"></i> Create invoice</a><?php endif;?></div></section>
<div class="mini-metrics finance-metrics"><div><span>Total invoiced</span><strong><?= money($totals['invoiced']) ?></strong></div><div><span>Payments received</span><strong><?= money($totals['paid']) ?></strong></div><div><span>Pending collection</span><strong><?= money($totals['pending']) ?></strong></div></div>
<section class="panel table-panel"><form class="filter-bar" method="get"><div class="search-control"><i class="fa-solid fa-magnifying-glass"></i><input name="q" value="<?= e($q) ?>" placeholder="Invoice number or client…"></div><label><span>Status</span><select name="status"><option value="">All statuses</option><?php foreach(['Draft','Sent','Partially Paid','Paid','Overdue','Cancelled'] as $s):?><option <?= $status===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach;?></select></label><button class="button button-secondary">Apply</button></form><div class="table-scroll"><table class="data-table"><thead><tr><th>Invoice</th><th>Client / project</th><th>Invoice date</th><th>Due date</th><th>Total</th><th>Paid</th><th>Pending</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><a class="table-link" href="<?= url('invoices/'.$row['id']) ?>"><?= e($row['invoice_number']) ?></a><small class="cell-sub"><?= e($row['invoice_type']) ?></small></td><td><strong><?= e($row['company_name']) ?></strong><small class="cell-sub"><?= e($row['project_name']?:'General billing') ?></small></td><td><?= e(date('d M Y',strtotime($row['invoice_date']))) ?></td><td class="<?= strtotime($row['due_date'])<strtotime('today')&&$row['pending_amount']>0?'text-danger':'' ?>"><?= e(date('d M Y',strtotime($row['due_date']))) ?></td><td><strong><?= money($row['grand_total']) ?></strong></td><td><?= money($row['paid_amount']) ?></td><td><?= money($row['pending_amount']) ?></td><td><span class="status-badge <?= status_class($row['status']) ?>"><?= e($row['status']) ?></span></td><td class="row-actions"><a class="icon-button" href="<?= url('invoices/'.$row['id']) ?>"><i class="fa-regular fa-eye"></i></a><a class="icon-button" href="<?= url('invoices/'.$row['id'].'/print') ?>" target="_blank"><i class="fa-solid fa-print"></i></a></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="9"><div class="empty-state"><span><i class="fa-solid fa-file-invoice-dollar"></i></span><h3>No invoices found</h3><p>Create the first invoice or adjust the filters.</p></div></td></tr><?php endif;?></tbody></table></div></section>
